// Command Center · Alert Simulator — posts synthetic alerts to the Events API v2 (platform path).
export default async function () {
  const scenarios = [
    { svc: "checkout", type: "PERFORMANCE_EVENT", title: "Checkout response time degraded", prio: "P2" },
    { svc: "checkout", type: "ERROR_EVENT", title: "Checkout failure rate increased", prio: "P1" },
    { svc: "payments", type: "AVAILABILITY_EVENT", title: "Payment gateway unreachable", prio: "P1" },
    { svc: "payments", type: "CUSTOM_ALERT", title: "Payment settlement batch delayed", prio: "P3" },
    { svc: "login", type: "ERROR_EVENT", title: "Login service returns HTTP 5xx", prio: "P2" },
    { svc: "inventory", type: "RESOURCE_CONTENTION_EVENT", title: "Inventory DB connection pool exhausted", prio: "P2" },
    { svc: "inventory", type: "CUSTOM_ALERT", title: "Inventory sync job failed", prio: "P4" },
    { svc: "storage", type: "RESOURCE_CONTENTION_EVENT", title: "Disk usage above 90% on file cluster", prio: "P3" },
    { svc: "network", type: "AVAILABILITY_EVENT", title: "Branch office VPN tunnel down", prio: "P2" },
    { svc: "backup", type: "CUSTOM_ALERT", title: "Nightly backup exceeded window", prio: "P5" },
    { svc: "search", type: "PERFORMANCE_EVENT", title: "Search latency p95 above SLO", prio: "P3" },
    { svc: "messaging", type: "CUSTOM_ALERT", title: "Message queue backlog growing", prio: "P3" },
  ];
  const n = 1 + Math.floor(Math.random() * 2);
  const sent = [];
  for (let i = 0; i < n; i++) {
    const s = scenarios[Math.floor(Math.random() * scenarios.length)];
    const body = {
      eventType: s.type,
      title: `[SIM] ${s.title}`,
      timeout: 10 + Math.floor(Math.random() * 50),
      properties: {
        "cc.service": s.svc,
        "cc.priority": s.prio,
        "cc.tags": `simulated,${s.svc}`,
        "cc.source": "alert-simulator",
      },
    };
    const r = await fetch("/platform/classic/environment-api/v2/events/ingest", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
    });
    sent.push({ title: body.title, status: r.status });
  }
  return { sent };
}
